"""Install safe copyable diagnostics and bounded isolated incident analysis."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile
from pathlib import Path
MANIFEST={'automation/server/runner.py': {'old': '33fdcaeebd4646dc46f1b3448e4d889f1ddb9dd8bb39afb5fc3d83c47fb0c083', 'new': 'de703650226f4616b5a88d60a4a49566518ce3df8ede05cbc5361a9a1dd4d6b9', 'body': ''}, 'automation/server/phone_tasks.py': {'old': '8b00bdaaa32635e39e8e0249f2d46da8aa19965364b6f396ac9cf14a97dfd34b', 'new': '706710216fc25e14bd7f827a87cb5ebe14d60efc8440ef46481e297674766df4', 'body': ''}, 'automation/server/phone_ui.py': {'old': 'baf6bfef2807c67365352c797a59aa4d74b9778fbb8159c8f7d519af35572ad1', 'new': '633f5ed7d06d2976d669663eb71b88e6e950bc1093d3911c8567d25742a150dd', 'body': ''}, 'automation/server/phone_view.py': {'old': '11db5485c2bf26324342018d62f3cb8a2fc58ba6e3f0d815bdbd7fb8f7fd6acd', 'new': '16993efedb7645e9590a951f526629cb6d01efa845d63439b4a5a8f6c9325051', 'body': ''}, 'automation/server/refresh_receipts.py': {'old': '720f0d8e69989a5edea838a03b73f703a08fc6595293f930c253480d278f9657', 'new': '4d662428b17b025d0939a9651c311793d38c4b2cfead06295a1920f06378d794', 'body': ''}, 'automation/server/incident_reports.py': {'old': None, 'new': '71aa3fc5ea6d328145c842a519449d9743426ce27be822830ed4e813ea7a5ec2', 'body': ''}, 'automation/server/test_incident_reports.py': {'old': None, 'new': '31243d10563cb9939a3f7a7f36d03b398d3bbdc248d62d3514feda6ac351cade', 'body': ''}, 'automation/server/test_incident_panel_browser.py': {'old': None, 'new': '8206a1aa2a53e2b6eb9367c4107126b8c82c37a7e1d768259c97508a149f57aa', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.handoff-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        if n.endswith('.py'):compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('incident-feedback-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(before);saved.chmod(0o600)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_incident_reports','test_phone_tasks','test_phone_view','test_refresh_receipts','test_phone_csrf','test_editor_handoff','test_recovery','test_install_recovery'],cwd=root/'automation/server',check=True,timeout=120)
            subprocess.run(['runuser','-u','fh6','--','/opt/fh6/venv/bin/python',str(root/'automation/server/test_incident_panel_browser.py')],cwd=root,check=True,timeout=120)
            subprocess.run(['/usr/bin/python3','automation/test_refresh_guard.py'],cwd=root,check=True,timeout=90)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True,timeout=10)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=False,timeout=30)
            raise
        print('INCIDENT_FEEDBACK_INSTALLED safe clipboard diagnostics; bounded isolated Codex proposals; no refresh or model task started',flush=True)
        print('BACKUP='+str(backup),flush=True)
        timer=subprocess.run(['systemctl','is-active','fh6-phone-tasks.timer'],capture_output=True,text=True,timeout=10)
        print('CODEX_TASK_TIMER='+('active' if timer.returncode==0 else 'inactive'),flush=True)
if __name__=='__main__':main()
